"""Reading and writing CSV tables for minisql.

A table is a CSV file whose first line is the header.  Fields are
converted to the value types described in SPEC.md: empty fields are NULL,
integer and decimal fields become ``int`` and ``float``, and everything
else stays a string.
"""

import csv
import re
from pathlib import Path
from typing import Any, Iterable, List, Optional, Sequence, TextIO, Tuple

from .errors import QueryError

__all__ = ["Table", "load_table", "format_value", "write_csv"]

# Full-match patterns.  ``re.fullmatch`` is used at conversion time so the
# whole field must match (``1e3`` and `` 1`` are strings, not numbers).
_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


class Table:
    """A loaded CSV table.

    ``columns`` holds the header names exactly as they appear in the file
    and ``rows`` holds tuples of converted values aligned with ``columns``.
    """

    __slots__ = ("columns", "rows")

    def __init__(
        self, columns: List[str], rows: Optional[List[Tuple[Any, ...]]] = None
    ) -> None:
        self.columns = list(columns)
        self.rows = list(rows) if rows is not None else []

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    __hash__ = None  # mutable

    def __repr__(self) -> str:
        return "Table({!r}, {!r})".format(self.columns, self.rows)


def _convert(field: str) -> Any:
    """Convert one CSV field to the corresponding minisql value."""
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory, name: str) -> Table:
    """Load ``<name>.csv`` from ``directory``.

    Raises :class:`minisql.errors.QueryError` if the file is missing,
    empty, unreadable, or contains a row whose width differs from the
    header.  Completely blank lines are ignored.
    """
    path = Path(directory) / (str(name) + ".csv")

    try:
        with path.open("r", newline="", encoding="utf-8") as stream:
            reader = csv.reader(stream)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError(
                    "table {!r}: file {!s} is empty (no header line)".format(
                        name, path
                    )
                ) from None

            if not header:
                raise QueryError(
                    "table {!r}: file {!s} has no header line".format(
                        name, path
                    )
                )

            rows: List[Tuple[Any, ...]] = []
            for line_number, record in enumerate(reader, start=2):
                # csv.reader yields [] for a completely blank line; such
                # lines (including a trailing blank line) carry no record.
                if not record:
                    continue
                if len(record) != len(header):
                    raise QueryError(
                        "table {!r}: line {} has {} field(s), expected {}".format(
                            name, line_number, len(record), len(header)
                        )
                    )
                rows.append(tuple(_convert(field) for field in record))
    except QueryError:
        raise
    except (FileNotFoundError, NotADirectoryError, IsADirectoryError) as exc:
        raise QueryError(
            "table {!r}: CSV file not found: {!s}".format(name, path)
        ) from exc
    except UnicodeDecodeError as exc:
        raise QueryError(
            "table {!r}: cannot decode CSV file {!s} as UTF-8: {}".format(
                name, path, exc
            )
        ) from exc
    except csv.Error as exc:
        raise QueryError(
            "table {!r}: malformed CSV file {!s}: {}".format(name, path, exc)
        ) from exc
    except OSError as exc:
        raise QueryError(
            "table {!r}: cannot read CSV file {!s}: {}".format(name, path, exc)
        ) from exc

    return Table(header, rows)


def format_value(value: Any) -> str:
    """Return the CSV field text for a minisql value."""
    if value is None:
        return ""
    # bool is a subclass of int, so it must be checked first.
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    if isinstance(value, str):
        return value
    return str(value)


def write_csv(
    columns: Sequence[str],
    rows: Iterable[Sequence[Any]],
    stream: TextIO,
) -> None:
    """Write ``columns`` and ``rows`` to ``stream`` as CSV.

    Uses Python's default ``csv`` dialect, so fields are quoted as needed
    and lines end with ``\\r\\n``.  NULL is an empty field and booleans
    are written as ``true``/``false``.
    """
    writer = csv.writer(stream)
    writer.writerow(list(columns))
    for row in rows:
        writer.writerow([format_value(value) for value in row])
